import { MouseEvent, createElement } from 'react';

import { c, msgid } from 'ttag';

import { Icon, IconName, Tooltip, classnames } from '@proton/components';

import { getNumAttachments } from '../../helpers/elements';
import { Element } from '../../models/element';

interface Props {
    element?: Element;
    className?: string;
    onClick?: (e: MouseEvent) => void;
    icon?: IconName;
}

const ItemAttachmentIcon = ({ element, className, onClick, icon = 'paper-clip' }: Props) => {
    const numAttachments = element ? getNumAttachments(element) : 0;
    const isButton = onClick !== undefined;

    if (numAttachments === 0) {
        return null;
    }

    const title = icon.includes('calendar')
        ? c('Calendar attachment tooltip').t`Has a calendar event`
        : c('Info').ngettext(
              msgid`Has ${numAttachments} attachment`,
              `Has ${numAttachments} attachments`,
              numAttachments
          );

    const commonProps = {
        className: classnames(['flex', className]),
        'data-testid': 'item-attachment-icon',
    };
    const buttonProps = {
        onClick,
        type: 'button',
    };

    return (
        <Tooltip title={title}>
            {createElement(
                isButton ? 'button' : 'div',
                { ...commonProps, ...(isButton ? buttonProps : {}) },
                <Icon name={icon} size={16} alt={title} />
            )}
        </Tooltip>
    );
};

export default ItemAttachmentIcon;

import { useMemo } from 'react';

import { fromUnixTime } from 'date-fns';
import { c } from 'ttag';

import { Icon, Tooltip, classnames } from '@proton/components';

import { formatFullDate } from '../../helpers/date';

import './ItemExpiration.scss';

interface Props {
    className?: string;
    expirationTime?: number;
}

const ItemExpiration = ({ className, expirationTime }: Props) => {
    const tooltipMessage = useMemo(() => {
        const date = fromUnixTime(expirationTime || 0);
        const formattedDate = formatFullDate(date);
        return c('Info').t`This message will expire ${formattedDate}`;
    }, [expirationTime]);

    if (!expirationTime) {
        return null;
    }

    return (
        // @ts-ignore
        <Tooltip title={tooltipMessage} className={classnames(['flex', className])}>
            <div className="pill-icon bg-global-warning" data-testid="item-expiration">
                <Icon name="hourglass" size={14} alt={tooltipMessage} />
            </div>
        </Tooltip>
    );
};

export default ItemExpiration;

